class Vault {
  readonly #store;                       // hard private: unreachable from outside, even via vault['#store']
  readonly #policy;
  constructor(store, policy) { this.#store = store; this.#policy = policy; }
  read(subject, id) {
    if (!this.#policy.allows(subject, id)) throw new Error(`denied: ${id}`);
    return this.#store.get(id);          // every exported path passes this check
  }
}
export const makeVault = (store, policy) => new Vault(store, policy);  // the only constructor
